// HasBundle applies the HasEdge predicate on the "bundle" edge.
func HasBundle() predicate.BundleFeaturedSlots {
	return predicate.BundleFeaturedSlots(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BundleTable, BundleColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBundleWith applies the HasEdge predicate on the "bundle" edge with a given conditions (other predicates).
func HasBundleWith(preds ...predicate.Bundles) predicate.BundleFeaturedSlots {
	return predicate.BundleFeaturedSlots(func(s *sql.Selector) {
		step := newBundleStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleFeaturedSlots) predicate.BundleFeaturedSlots {
	return predicate.BundleFeaturedSlots(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleFeaturedSlots) predicate.BundleFeaturedSlots {
	return predicate.BundleFeaturedSlots(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleFeaturedSlots) predicate.BundleFeaturedSlots {
	return predicate.BundleFeaturedSlots(sql.NotPredicates(p))
}
